import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import process from 'node:process';

function validateRoot(root) {
  const stat = fs.lstatSync(root);
  if (!stat.isDirectory() || stat.isSymbolicLink()) throw Error('root must be a non-symlink directory');
}
function validatePath(selected) {
  if (typeof selected !== 'string' || !selected || selected.startsWith('/')
    || selected.includes('\\') || selected.includes('\0')
    || selected.split('/').some(part => !part || part === '.' || part === '..')) throw Error('invalid selected path');
}
function inspect(root, selected) {
  const parts = selected.split('/'); let current = root;
  for (let i = 0; i < parts.length; i++) {
    current = path.join(current, parts[i]);
    let stat;
    try { stat = fs.lstatSync(current); }
    catch (error) { if (error.code === 'ENOENT') return {kind:'missing'}; throw error; }
    if (stat.isSymbolicLink() || (i === parts.length - 1 ? !stat.isFile() : !stat.isDirectory())) return {kind:'unsafe'};
    if (i === parts.length - 1) {
      const bytes = fs.readFileSync(current);
      return {kind:'file',sha256:crypto.createHash('sha256').update(bytes).digest('hex'),size:bytes.length,mode:stat.mode & 0o777};
    }
  }
}
export function createManifest(root, paths) {
  validateRoot(root);
  if (!Array.isArray(paths)) throw Error('paths must be an array');
  const seen = new Set();
  for (const selected of paths) {
    validatePath(selected);
    if (seen.has(selected)) throw Error('duplicate selection');
    seen.add(selected);
  }
  return {version:1,files:[...paths].sort().map(selected => {
    const current = inspect(root, selected);
    if (current.kind !== 'file') throw Error(`${current.kind} selected path`);
    return {path:selected,sha256:current.sha256,size:current.size,mode:current.mode};
  })};
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}
function validateManifest(manifest) {
  if (!isPlainObject(manifest)) throw Error('manifest must be a non-null non-array object');
  if (manifest.version !== 1) throw Error('manifest version must be exactly 1');
  if (!Array.isArray(manifest.files)) throw Error('manifest files must be an array');
  const seen = new Set();
  for (const entry of manifest.files) {
    if (!isPlainObject(entry)) throw Error('manifest entry must be a non-null non-array object');
    const selected = entry.path;
    validatePath(selected);
    if (seen.has(selected)) throw Error('duplicate manifest path');
    seen.add(selected);
    if (typeof entry.sha256 !== 'string' || !/^[0-9a-f]{64}$/.test(entry.sha256)) throw Error('manifest sha256 must be 64 lowercase hexadecimal characters');
    if (typeof entry.size !== 'number' || !Number.isSafeInteger(entry.size) || entry.size < 0) throw Error('manifest size must be a nonnegative safe integer');
    if (typeof entry.mode !== 'number' || !Number.isInteger(entry.mode) || entry.mode < 0 || entry.mode > 511) throw Error('manifest mode must be an integer in 0..511');
  }
}
export function verifyManifest(root, manifest) {
  validateRoot(root);
  validateManifest(manifest);
  const unchanged = [], changed = [], missing = [], unsafe = [];
  for (const entry of [...manifest.files].sort((a, b) => (a.path < b.path ? -1 : a.path > b.path ? 1 : 0))) {
    const selected = entry.path;
    const parts = selected.split('/'); let current = root;
    let status = 'ok';
    for (let i = 0; i < parts.length; i++) {
      current = path.join(current, parts[i]);
      let stat;
      try { stat = fs.lstatSync(current); }
      catch (error) { if (error.code === 'ENOENT') { status = 'missing'; break; } throw error; }
      if (stat.isSymbolicLink() || (i === parts.length - 1 ? !stat.isFile() : !stat.isDirectory())) { status = 'unsafe'; break; }
    }
    if (status === 'missing') { missing.push(selected); continue; }
    if (status === 'unsafe') { unsafe.push(selected); continue; }
    const bytes = fs.readFileSync(current);
    const reasons = [];
    if (bytes.length !== entry.size || crypto.createHash('sha256').update(bytes).digest('hex') !== entry.sha256) reasons.push('content');
    if ((fs.lstatSync(current).mode & 0o777) !== entry.mode) reasons.push('mode');
    if (reasons.length) changed.push({path:selected,reasons}); else unchanged.push(selected);
  }
  return {ok:changed.length === 0 && missing.length === 0 && unsafe.length === 0, unchanged, changed, missing, unsafe};
}

function main(argv) {
  const [command, ...rest] = argv;
  if (command === 'create') {
    if (rest.length < 1) throw Error('usage: node snapshot.js create ROOT [PATH ...]');
    const manifest = createManifest(rest[0], rest.slice(1));
    process.stdout.write(`${JSON.stringify(manifest)}\n`);
    return 0;
  }
  if (command === 'verify') {
    if (rest.length !== 2) throw Error('usage: node snapshot.js verify ROOT MANIFEST_FILE');
    let manifest;
    try { manifest = JSON.parse(fs.readFileSync(rest[1], 'utf8')); }
    catch (error) { throw Error(`cannot read manifest file: ${error.message}`); }
    const report = verifyManifest(rest[0], manifest);
    process.stdout.write(`${JSON.stringify(report)}\n`);
    return report.ok ? 0 : 1;
  }
  throw Error('usage: node snapshot.js create ROOT [PATH ...] | node snapshot.js verify ROOT MANIFEST_FILE');
}

if (process.argv[1] && import.meta.url === `file://${process.argv[1]}`) {
  let code = 0;
  try { code = main(process.argv.slice(2)); }
  catch (error) { process.stderr.write(`${error.message}\n`); code = 2; }
  process.exitCode = code;
}

